mapper.select:
SELECT sct.sctid, s.sid, s.sname, c.cid, c.cname, t.tid, t.tname, sct.grade, sct.term, (SELECT MAX(wf.created_at) FROM studentms.warning_followup wf WHERE wf.sctid = sct.sctid) AS lastFollowupAt FROM studentms.sct sct INNER JOIN studentms.s s ON sct.sid = s.sid INNER JOIN studentms.c c ON sct.cid = c.cid INNER JOIN studentms.t t ON sct.tid = t.tid WHERE sct.grade < 60
AND sct.term = #{term}
AND sct.cid = #{cid}
AND sct.tid = #{tid}
ORDER BY sct.term DESC, c.cname, s.sid

SELECT id, sctid, content, operator_tid AS operatorTid, created_at AS createdAt
FROM studentms.warning_followup
WHERE id = #{id}
